import { describe, expect, it } from 'vitest';

import { fieldsFromSchema, humanize } from './schema';

// Schema generated by Astro for a real blog, with an extra .describe() and .max().
const blog = {
  type: 'object',
  properties: {
    title: { type: 'string', description: 'Title' },
    description: { type: 'string', maxLength: 160 },
    pubDate: { type: 'string', format: 'date-time' },
    cover: { type: 'string' },
    coverAlt: { type: 'string' },
    tags: { type: 'array', items: { type: 'string' } },
    draft: { default: false, type: 'boolean' },
    meta: { type: 'object' },
    $schema: { type: 'string' },
  },
  required: ['title', 'description', 'pubDate'],
};

describe('fieldsFromSchema', () => {
  it('deduz os campos do schema do Astro', () => {
    const fields = fieldsFromSchema(blog, { fields: { coverAlt: { label: 'Image description' } } });

    expect(fields.map((f) => [f.name, f.widget])).toEqual([
      ['title', 'string'],
      ['description', 'text'],
      ['pubDate', 'datetime'],
      ['cover', 'image'],
      ['coverAlt', 'string'],
      ['tags', 'list'],
      ['draft', 'boolean'],
      ['body', 'markdown'],
    ]);
    expect(fields[0]).toMatchObject({ label: 'Title', required: true });
    expect(fields[1]).toMatchObject({ maxlength: 160, label: 'Description' });
    expect(fields[3]).toMatchObject({ required: false });
    expect(fields[4]).toMatchObject({ label: 'Image description' });
    expect(fields[6]).toMatchObject({ default: false });
  });

  it('humaniza nomes', () => {
    expect(humanize('pubDate')).toBe('Pub date');
    expect(humanize('instagram_caption')).toBe('Instagram caption');
  });
});
